def transform(grid):
    """Overlay the two marked regions on either side of a solid separator."""
    h, w = len(grid), len(grid[0])
    # A uniform nonzero line separates two aligned binary pictures.
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            a, b = grid[:r], grid[r + 1:]
            if a and len(a) == len(b):
                return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                         for j in range(w)] for i in range(len(a))]
    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            if a and len(a[0]) == len(b[0]):
                return [[2 if a[i][j] != 0 and b[i][j] != 0 else 0
                         for j in range(len(a[0]))] for i in range(h)]
    raise ValueError("No aligned solid separator found")

def transform(grid):
    """Extract rows after a uniform separator whose color is absent below; recolor 8 to 2."""
    h = len(grid)
    candidates = []
    for r, row in enumerate(grid):
        color = row[0]
        if color != 0 and all(value == color for value in row):
            if all(color not in below for below in grid[r + 1:]):
                candidates.append(r)
    if not candidates:
        raise ValueError("No uniform separator absent from the lower region")
    r = candidates[-1]
    return [[2 if value == 8 else 0 for value in row] for row in grid[r + 1:]]

